 var main='<div class="tchd"><h2>'+esc(T.title)+'</h2>'+cnt+'</div><p class="tclead">'+esc(T.lead)+'</p>'+(h||'<div class="tcem">'+ICALP+'<h3>'+esc(T.empty_title)+'</h3><p>'+esc(T.empty_text)+'</p><button type="button" data-tccard>'+esc(T.empty_btn)+'</button></div>')+'<p class="tcst">'+esc(T.storage)+'</p>';
