var VIEWS=['vreg','vmet','vsrc','vrep','vprc','vfin','vprop','vman','favseg','vval','vrpt','vupd'];
function openView(){if(!V)return;closeMenu();var nav=document.querySelector('nav'),bar=document.getElementById('othbar');if(nav)nav.querySelectorAll('button').forEach(function(x){x.classList.toggle('on',x===NB)});
 VIEWS.forEach(function(i){var e=document.getElementById(i);if(e)e.style.display='none'});if(bar){bar.style.display='none';bar.querySelectorAll('button').forEach(function(x){x.classList.toggle('on',x===OB)})}
 if(CALB)CALB.classList.add('on');render();V.style.display='';scrollTo(0,0)}
function hideView(){if(!V||V.style.display==='none')return;V.style.display='none';if(NB)NB.classList.remove('on');if(OB)OB.classList.remove('on');if(CALB)CALB.classList.remove('on')}
function go(s,id){hideView();closeMenu();if(window.EV_GOTO)window.EV_GOTO(s,id,T.focus_label)}
function mount(){if(V||!on())return;var nav=document.querySelector('nav'),bar=document.getElementById('othbar');if(!nav)return;css();
 NB=document.createElement('button');NB.dataset.v='tcal';NB.className='evx';NB.title=T.title;NB.textContent=T.nav;NB.style.display='none';nav.appendChild(NB);NB.addEventListener('click',openView);
 if(bar){OB=document.createElement('button');OB.dataset.o='tcal';OB.title=T.title;OB.innerHTML=ICAL+esc(T.nav);bar.insertBefore(OB,bar.querySelector('button[data-o="cfg"]')||null);OB.addEventListener('click',function(e){e.stopPropagation();openView()})}
 V=document.createElement('div');V.id='vtcal';V.style.display='none';V.innerHTML='<div class="md"><div class="tcw"></div></div>';
 var after=document.getElementById('vupd')||document.getElementById('vrpt')||document.getElementById('vrep');(after&&after.parentNode||document.body).insertBefore(V,after?after.nextSibling:null);
 V.addEventListener('click',function(e){var o;
  if(e.target.closest('[data-tcsw]')){o=nload();o.enabled=!o.enabled;nstore(o);render();refresh();return}
  var ld=e.target.closest('[data-tclead]');if(ld){o=nload();o.leadDays=+ld.dataset.tclead;nstore(o);render();refresh();return}
  var dy=e.target.closest('[data-tcday]');if(dy){var g=V.querySelector('[data-tcg="'+dy.dataset.tcday+'"]')||V.querySelector('.tcr[data-day="'+dy.dataset.tcday+'"]');if(g)g.scrollIntoView({block:'start',behavior:'smooth'});return}
  if(e.target.closest('[data-tccard]')){hideView();if(typeof window.goTab==='function')window.goTab('reg');return}
  var r=e.target.closest('.tcr');if(!r)return;var k=r.getAttribute('data-tck').split('|'),s=k[0],n=+k.pop(),id=k.slice(1).join('|');
  if(e.target.closest('[data-tcdel]')){var g2=del(s,id,n);render();toast(T.toast_remove,T.toast_undo,function(){add(s,id,n,g2);render()});return}if(e.target.closest('[data-tcgo]'))go(s,id)});
 document.addEventListener('click',function(ev){var x=ev.target.closest&&ev.target.closest('button');if(!x||x===NB||x===OB||x===BELL||x===CALB||(MENU&&MENU.contains(x)))return;if(nav.contains(x)||x.id==='urb'||x.id==='oth'||(bar&&bar.contains(x)))hideView()},true);
 BELL=document.createElement('button');BELL.type='button';BELL.id='tcbell';BELL.className='tchb';BELL.title=NT.bell_hint;BELL.setAttribute('aria-haspopup','true');BELL.setAttribute('aria-expanded','false');BELL.innerHTML=IBELL+'<span class="n"></span>';BELL.addEventListener('click',function(e){e.stopPropagation();if(MENU)closeMenu();else openMenu()});
 CALB=document.createElement('button');CALB.type='button';CALB.id='tccalb';CALB.className='tchb';CALB.innerHTML=ICAL;CALB.title=NT.cal_hint;CALB.setAttribute('aria-label',NT.cal);CALB.addEventListener('click',function(e){e.stopPropagation();openView()});
 document.addEventListener('click',function(e){if(MENU&&!MENU.contains(e.target)&&e.target!==BELL&&!BELL.contains(e.target))closeMenu()});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&MENU){closeMenu();BELL.focus()}});
 placeBell();refresh()}
function placeBell(){if(!BELL)return;var ax=document.querySelector('#h3in .h3a');
 if(ax){if(BELL.parentNode!==ax||CALB.parentNode!==ax||ax.lastChild!==CALB){ax.appendChild(BELL);ax.appendChild(CALB)}ax.classList.add('tch');return}
 var th=document.getElementById('thm');if(th&&th.parentNode&&(BELL.parentNode!==th.parentNode||th.nextSibling!==BELL)){th.parentNode.insertBefore(BELL,th.nextSibling);th.parentNode.insertBefore(CALB,BELL.nextSibling)}}
