function openMenu(){if(!BELL)return;closeMenu();var ns=nload(),L=notes();MENU=document.createElement('div');MENU.id='tcmenu';MENU.setAttribute('role','dialog');MENU.setAttribute('aria-label',NT.title);
 MENU.innerHTML='<div class="hd"><b>'+esc(NT.title)+'</b>'+(L.some(function(n){return n.unread})?'<button type="button" data-tcall>'+esc(NT.mark_all)+'</button>':'')+'</div><div class="ls">'+(L.length?L.map(noteHtml).join(''):'<div class="em">'+esc(ns.enabled?NT.empty:NT.empty_off)+'</div>')+'</div><div class="ft"><button type="button" data-tccal>'+ICAL+esc(NT.to_cal)+'</button></div>';
 document.body.appendChild(MENU);var b=BELL.getBoundingClientRect(),w=MENU.offsetWidth;MENU.style.top=Math.round(b.bottom+8)+'px';MENU.style.left=Math.max(8,Math.min(innerWidth-w-8,Math.round(b.right-w)))+'px';
 if(innerWidth<=(Z.bp_phone||480)){var hd=document.querySelector('header');MENU.style.top=Math.round((hd?hd.getBoundingClientRect().bottom:b.bottom)+4)+'px'}
 BELL.setAttribute('aria-expanded','true');
 MENU.addEventListener('click',function(e){e.stopPropagation();if(e.target.closest('[data-tcall]')){markRead(notes().map(function(n){return n.id}));openMenu();return}if(e.target.closest('[data-tccal]')){openView();return}
  var it=e.target.closest('[data-tcn-id]');if(it){markRead([it.getAttribute('data-tcn-id')]);var k=it.getAttribute('data-tck').split('|');go(k[0],k.slice(1).join('|'))}})}
