var BAN_SHOWN=false;
function bannerNote(){var L=notes().filter(function(n){return n.unread});var up=L.filter(function(n){return n.type!=='after'}).sort(function(a,b){return a.r.t-b.r.t});return {n:up[0]||null,more:L.length-(up[0]?1:0)}}
function showBanner(){var B=bannerNote(),n=B.n;if(document.getElementById('tcban')||!n)return;var hd=document.querySelector('header');if(!hd)return;var r=n.r,b=document.createElement('div');b.id='tcban';b.className='tcban';b.setAttribute('role','status');b.setAttribute('aria-label',NT.banner_aria);
 b.innerHTML='<span class="ic">'+IBELL+'</span><div class="tx">'+ntext(r,n.type)+'<span class="sub">'+esc(fmt(T.stage,{n:r.n,m:r.m}))+' · '+esc(fmt(T.reduction,{dt:dtT(r.t)}))+(B.more>0?' · <button type="button" data-tcmore>'+esc(fmt(NT.banner_more,{count:plural(B.more,'notes')}))+'</button>':'')+'</span></div><div class="ac"><button type="button" data-tcgo>'+esc(NT.banner_open)+'</button><button type="button" class="ok" data-tcok>'+esc(NT.banner_ok)+'</button></div>';
 b.addEventListener('click',function(e){if(e.target.closest('[data-tcmore]')){e.stopPropagation();openMenu();return}if(e.target.closest('[data-tcok]')){markRead([n.id]);b.remove();return}if(e.target.closest('[data-tcgo]')){markRead([n.id]);b.remove();go(r.x.scope,r.x.lot)}});
 hd.parentNode.insertBefore(b,hd.nextSibling)}
function refresh(){if(!on()){tick();return}if(!V)mount();if(!V)return;placeBell();var L=notes(),un=L.filter(function(n){return n.unread}).length;
 if(BELL){BELL.style.display='';var c=BELL.querySelector('.n'),t=un?String(un):'';if(c.textContent!==t)c.textContent=t;var tt=NT.bell+(un?': '+plural(un,'notes'):'');if(BELL.getAttribute('aria-label')!==tt)BELL.setAttribute('aria-label',tt)}
 var ban=document.getElementById('tcban');if(ban&&!bannerNote().n)ban.remove();
 if(!BAN_SHOWN&&lots('reg').length+lots('prop').length>0){BAN_SHOWN=true;showBanner()}
 sync()}
function tick(){try{if(!on()){[BELL,CALB,document.getElementById('tcban')].forEach(function(e){if(e)e.style.display='none'});closeMenu();hideView();return}[BELL,CALB].forEach(function(e){if(e&&e.style.display==='none')e.style.display=''});refresh()}catch(e){}}
